CREATE TABLE "RutasProduccion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProductoId" integer NOT NULL,
    "Version" integer NOT NULL,
    "Estado" character varying(8) NOT NULL,
    CONSTRAINT "PK_RutasProduccion" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RutasProduccion_Productos_ProductoId"
        FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_RutasProduccion_Version" CHECK ("Version" > 0),
    CONSTRAINT "CK_RutasProduccion_Estado" CHECK ("Estado" IN ('Borrador', 'Activa', 'Retirada'))
);

CREATE UNIQUE INDEX "IX_RutasProduccion_ProductoId_Version"
    ON "RutasProduccion" ("ProductoId", "Version");
CREATE UNIQUE INDEX "IX_RutasProduccion_ProductoId_Activa"
    ON "RutasProduccion" ("ProductoId", "Estado") WHERE "Estado" = 'Activa';

CREATE TABLE "OperacionesRutaProduccion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RutaProduccionId" integer NOT NULL,
    "Secuencia" integer NOT NULL,
    "Nombre" character varying(120) NOT NULL,
    "CentroTrabajoId" integer NOT NULL,
    "MinutosPreparacion" numeric(10, 2) NOT NULL,
    "MinutosPorUnidad" numeric(10, 2) NOT NULL,
    CONSTRAINT "PK_OperacionesRutaProduccion" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OperacionesRutaProduccion_RutasProduccion_RutaProduccionId"
        FOREIGN KEY ("RutaProduccionId") REFERENCES "RutasProduccion" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_OperacionesRutaProduccion_CentrosTrabajo_CentroTrabajoId"
        FOREIGN KEY ("CentroTrabajoId") REFERENCES "CentrosTrabajo" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_OperacionesRutaProduccion_Secuencia" CHECK ("Secuencia" BETWEEN 1 AND 100),
    CONSTRAINT "CK_OperacionesRutaProduccion_Tiempos" CHECK ("MinutosPreparacion" >= 0 AND "MinutosPorUnidad" > 0)
);

CREATE UNIQUE INDEX "IX_OperacionesRutaProduccion_RutaProduccionId_Secuencia"
    ON "OperacionesRutaProduccion" ("RutaProduccionId", "Secuencia");
CREATE INDEX "IX_OperacionesRutaProduccion_CentroTrabajoId"
    ON "OperacionesRutaProduccion" ("CentroTrabajoId");
